public static int findNthLeapYear(int Y, int N) {
    while (N > 0) {
        Y = Y + 1;
        if (isLeapYear(Y)) N--;
    }
    return Y;
}

private static boolean isLeapYear(int year) {
    // A leap year is exactly divisible by 4 except for end of centuries that are not divisible by 400
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}
