public class PermuteAll {
    public List<List<Integer>> permute(int[] nums) {
        // Initialize the result list to hold the permutations
        List<List<Integer>> result = new ArrayList<>();
        // Helper function to rotate subarray from start to end
        void rotate(int[] arr, int start, int end) {
            while (start < end) {
                int temp = arr[start];
                arr[start] = arr[end];
                arr[end] = temp;
                start++;
                end--;
            }
        }

        // Helper function to generate permutations using backtracking
        void backtrack(List<List<Integer>> result, int[] nums, int offset) {
            // If the current offset equals the length of the array, add to the result
            if (offset == nums.length) {
                result.add(new ArrayList<>(Arrays.asList(nums)));
                return;
            }
            // Iterate through the remaining elements to swap with the current offset
            for (int i = offset; i < nums.length; i++) {
                // Swap the current element with the element at the offset
                swap(nums, offset, i);
                // Recursively generate permutations for the remaining elements
                backtrack(result, nums, offset + 1);
                // backtrack by restoring the original order
                swap(nums, offset, i);
            }
        }

        // Helper function to swap two elements in an array
        void swap(int[] arr, int first, int second) {
            int temp = arr[first];
            arr[first] = arr[second];
            arr[second] = temp;
        }

        // Generate and return all permutations
        backtrack(result, nums, 0);
        return result;
    }
}
