import java.util.stream.IntStream;

public static String appx(String word1, String word2) {
    int commonChars = IntStream.range(0, Math.min(word1.length(), word2.length()))
                              .filter(i -> word1.charAt(i) == word2.charAt(i))
                              .count();
    int totalChars = word1.length() + word2.length();
    int gcd = gcd(commonChars, totalChars);
    int reducedCommonChars = commonChars / gcd;
    int reducedTotalChars = totalChars / gcd;

    return String.format("appx(%s, %s) = %d/%d", word1, word2, reducedCommonChars, reducedTotalChars);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
