    pq.offer(1L);
    Set<Long> visited = new HashSet<>();
    visited.add(1L);

    for (int i = 1; i < n; i++) {
        long currUgly = pq.poll();

        for (long nextUgly : new long[]{currUgly * 2, currUgly * 3, currUgly * 5}) {
            if (!visited.contains(nextUgly)) {
                pq.offer(nextUgly);
